mapper.select:
SELECT r.ID, r.PARTNER_ID, r.LIST_TYPE, r.LIST_REASON, r.RISK_LEVEL, r.BUSINESS_SCOPE, r.RESTRICTION_DETAILS, r.EVIDENCE_MATERIALS, r.REVIEW_PERIOD, r.NEXT_REVIEW_DATE, r.EFFECTIVE_DATE, r.EXPIRE_DATE, r.APPROVAL_USER, r.APPROVAL_TIME, r.REMOVAL_REASON, r.REMOVAL_USER, r.REMOVAL_TIME, r.STATUS, r.REMARK, r.CREATE_TIME, r.UPDATE_TIME, r.CREATE_USER, r.UPDATE_USER, r.VERSION_NO, p.PARTNER_CODE, p.PARTNER_NAME, p.PARTNER_TYPE_ID FROM TC_PARTNER_RISK_LIST r LEFT JOIN TC_PARTNER_ARCHIVE p ON r.PARTNER_ID = p.ID
AND r.PARTNER_ID = #{params.partnerId}
AND p.PARTNER_CODE LIKE CONCAT('%', #{params.partnerCode}, '%')
AND p.PARTNER_NAME LIKE CONCAT('%', #{params.partnerName}, '%')
AND r.LIST_TYPE = #{params.listType}
AND r.RISK_LEVEL = #{params.riskLevel}
AND r.STATUS = #{params.riskStatus}
AND r.LIST_TYPE = #{params.assessmentType}
ORDER BY r.CREATE_TIME DESC
